export type InstallationChannel = 'local' | 'production';

export const installationChannel = (
  env: NodeJS.ProcessEnv = process.env,
): InstallationChannel => {
  const channel =
    env.RIVET_CHANNEL ??
    (env.NODE_ENV === 'development' ? 'local' : 'production');
  if (channel !== 'local' && channel !== 'production')
    throw new Error(`Unknown Rivet channel: ${channel}`);
  return channel;
};
